.cursor/hooks.json:
{
    "version": 1,
    "hooks": {
        "sessionStart": [
            {
                "command": "[ -x ./agent-config ] || exit 0; ./agent-config dispatch:hook --platform cursor --event session_start --native-event sessionStart"
            }
        ],
        "sessionEnd": [
            {
                "command": "[ -x ./agent-config ] || exit 0; ./agent-config dispatch:hook --platform cursor --event session_end --native-event sessionEnd"
            }
        ],
        "stop": [
            {
                "command": "[ -x ./agent-config ] || exit 0; ./agent-config dispatch:hook --platform cursor --event stop --native-event stop"
            }
        ],
        "beforeSubmitPrompt": [
            {
                "command": "[ -x ./agent-config ] || exit 0; ./agent-config dispatch:hook --platform cursor --event user_prompt_submit --native-event beforeSubmitPrompt"
            }
        ],
        "postToolUse": [
            {
                "command": "[ -x ./agent-config ] || exit 0; ./agent-config dispatch:hook --platform cursor --event post_tool_use --native-event postToolUse"
            }
        ]
    }
}

